259	static int esp_imgdata_set_buf(FAR struct imgdata_s *data,
260	                               uint8_t nr_datafmts,
261	                               FAR imgdata_format_t *datafmts,
262	                               uint8_t *addr, uint32_t size)
263	{
264	  /* Record the next DMA destination buffer. This is called both before
265	   * start_capture (initial buffer) and from the frame-done path (via the
266	   * V4L2 complete_capture handler) to supply the next buffer.
267	   */
268	
269	  g_esp_cam_data.next_buf  = addr;
270	  g_esp_cam_data.next_size = size;
271	  esp_csi_set_buffer(addr, size);
272	  return OK;
273	}
