275	static int esp_imgdata_validate_frame(FAR struct imgdata_s *data,
276	                                      uint8_t nr_datafmts,
277	                                      FAR imgdata_format_t *datafmts,
278	                                      FAR imgdata_interval_t *interval)
279	{
280	  if (nr_datafmts < 1 || datafmts == NULL)
