297	/****************************************************************************
298	 * Name: esp_cam_frame_done
299	 *
300	 * Description:
301	 *   Invoked from the DW-GDMA ISR when a frame completes. Hands the filled
302	 *   buffer up to the V4L2 layer via capture_cb (which synchronously queues
303	 *   the next buffer through esp_imgdata_set_buf) and returns that next
304	 *   buffer to the ISR so it can re-arm the DMA.
305	 ****************************************************************************/
306	
307	static int esp_cam_frame_done(FAR void *arg,
308	                              FAR uint8_t **next_buf,
309	                              FAR uint32_t *next_size)
310	{
311	  struct timeval ts;
312	
313	  /* Invalidate stale "next" so we can detect whether the V4L2 layer
314	   * supplied a fresh buffer during the capture callback.
315	   */
316	
317	  g_esp_cam_data.next_buf = NULL;
318	
319	  if (g_esp_cam_data.capture_cb != NULL)
320	    {
321	      gettimeofday(&ts, NULL);
322	
323	      /* Report a completed RGB565 frame. complete_capture() will call
324	       * esp_imgdata_set_buf() synchronously with the next buffer.
325	       */
326	
327	      g_esp_cam_data.capture_cb(0, ESP_CSI_FRAME_SIZE,
328	                                &ts, g_esp_cam_data.capture_arg);
329	    }
330	
331	  *next_buf  = g_esp_cam_data.next_buf;
332	  *next_size = g_esp_cam_data.next_size;
333	  return OK;
334	}
