336	static int esp_imgdata_start_capture(FAR struct imgdata_s *data,
337	                                     uint8_t nr_datafmts,
338	                                     FAR imgdata_format_t *datafmts,
339	                                     FAR imgdata_interval_t *interval,
340	                                     FAR imgdata_capture_t callback,
341	                                     FAR void *arg)
342	{
343	  int ret;
344	
345	  syslog(LOG_INFO, "ESP Camera: start_capture\n");
346	
347	  g_esp_cam_data.capture_cb = callback;
348	  g_esp_cam_data.capture_arg = arg;
349	
350	  /* Register the DMA frame-done callback with the CSI driver */
351	
352	  esp_csi_register_frame_cb(esp_cam_frame_done, NULL);
353	
354	  /* Start the CSI controller (arms DMA + enables bridge) */
355	
356	  ret = esp_csi_start();
357	  if (ret < 0)
358	    {
359	      return ret;
360	    }
361	
362	  g_esp_cam_data.streaming = true;
363	  return OK;
364	}
365	
366	static int esp_imgdata_stop_capture(FAR struct imgdata_s *data)
367	{
368	  syslog(LOG_INFO, "ESP Camera: stop_capture\n");
369	
370	  g_esp_cam_data.streaming = false;
371	  g_esp_cam_data.capture_cb = NULL;
372	  g_esp_cam_data.capture_arg = NULL;
373	
374	  return esp_csi_stop();
375	}
