70	int board_fb_initialize(void)
71	{
72	  int ret;
73	  uint8_t *fb;
74	
75	  /* Get framebuffer from DSI driver (already initialized by bringup) */
76	
77	  fb = esp_dsi_fb_get_buffer();
78	  if (fb == NULL)
79	    {
80	      syslog(LOG_ERR, "ERROR: DSI framebuffer not available\n");
81	      return -ENOMEM;
82	    }
83	
84	  /* Fill plane info */
85	
86	  g_planeinfo.fbmem        = (void *)fb;
87	  g_planeinfo.fblen        = FB_SIZE;
88	  g_planeinfo.stride       = FB_STRIDE;
89	  g_planeinfo.bpp          = FB_BPP;
90	  g_planeinfo.display      = 0;
91	  g_planeinfo.xres_virtual = FB_XRES;
92	  g_planeinfo.yres_virtual = FB_YRES;
93	  g_planeinfo.xoffset      = 0;
94	  g_planeinfo.yoffset      = 0;
95	
96	  /* Register /dev/fb0 */
97	
98	  ret = fb_register_device(0, 0, &g_vtable);
99	  if (ret < 0)
100	    {
101	      syslog(LOG_ERR, "ERROR: fb_register_device failed: %d\n", ret);
102	      return ret;
103	    }
104	
105	  syslog(LOG_INFO, "Framebuffer registered at /dev/fb0 (%dx%d, %d bpp)\n",
106	         FB_XRES, FB_YRES, FB_BPP);
107	  return OK;
108	}
109

500	 *   destination buffer already validated (non-NULL, large enough).
501	 ****************************************************************************/
502	
503	static void esp_csi_dma_arm(FAR uint8_t *dst)
504	{
505	  dw_gdma_dev_t *dev = DW_GDMA_LL_GET_HW(0);
506	  const uint8_t ch = ESP_CSI_DMA_CHANNEL;
507	
508	  /* Source: CSI bridge FIFO, fixed address, 64-bit, burst 512/16 */
509	
510	  dw_gdma_ll_channel_set_src_addr(dev, ch, ESP_CSI_BRG_MEM_BASE);
511	  dw_gdma_ll_channel_set_src_burst_mode(dev, ch, DW_GDMA_BURST_MODE_FIXED);
512	  dw_gdma_ll_channel_set_src_trans_width(dev, ch, DW_GDMA_TRANS_WIDTH_64);
513	  dw_gdma_ll_channel_set_src_burst_items(dev, ch, DW_GDMA_BURST_ITEMS_512);
514	  dw_gdma_ll_channel_set_src_burst_len(dev, ch, 16);
515	  dw_gdma_ll_channel_set_src_master_port(dev, ch, ESP_CSI_BRG_MEM_BASE);
516	
517	  /* Destination: frame buffer, incrementing address, 64-bit */
518	
519	  dw_gdma_ll_channel_set_dst_addr(dev, ch, (uint32_t)(uintptr_t)dst);
520	  dw_gdma_ll_channel_set_dst_burst_mode(dev, ch, DW_GDMA_BURST_MODE_INCREMENT);
521	  dw_gdma_ll_channel_set_dst_trans_width(dev, ch, DW_GDMA_TRANS_WIDTH_64);
522	  dw_gdma_ll_channel_set_dst_burst_items(dev, ch, DW_GDMA_BURST_ITEMS_512);
523	  dw_gdma_ll_channel_set_dst_burst_len(dev, ch, 16);
524	  dw_gdma_ll_channel_set_dst_master_port(dev, ch, (uintptr_t)dst);
525	
526	  /* One RAW8 frame worth of 64-bit items */
527	
528	  dw_gdma_ll_channel_set_trans_block_size(dev, ch, ESP_CSI_DMA_XFER_ITEMS);
529	
530	  /* Contiguous single-block transfer, source is flow controller (CSI) */
531	
532	  dw_gdma_ll_channel_set_src_multi_block_type(dev, ch,
533	                                     DW_GDMA_BLOCK_TRANSFER_CONTIGUOUS);
534	  dw_gdma_ll_channel_set_dst_multi_block_type(dev, ch,
535	                                     DW_GDMA_BLOCK_TRANSFER_CONTIGUOUS);
536	  dw_gdma_ll_channel_set_trans_flow(dev, ch, DW_GDMA_ROLE_PERIPH_CSI,
537	                                    DW_GDMA_ROLE_MEM, DW_GDMA_FLOW_CTRL_SRC);
538	
539	  /* Hardware handshake, CSI as source peripheral */
540	
541	  dw_gdma_ll_channel_set_src_handshake_interface(dev, ch,
542	                                                 DW_GDMA_HANDSHAKE_HW);
543	  dw_gdma_ll_channel_set_dst_handshake_interface(dev, ch,
544	                                                 DW_GDMA_HANDSHAKE_HW);
545	  dw_gdma_ll_channel_set_src_handshake_periph(dev, ch,
546	                                              DW_GDMA_ROLE_PERIPH_CSI);
547	  dw_gdma_ll_channel_set_src_outstanding_limit(dev, ch, 5);
548	  dw_gdma_ll_channel_set_dst_outstanding_limit(dev, ch, 5);
549	  dw_gdma_ll_channel_set_priority(dev, ch, 1);
550	
551	  /* Enable block-transfer-done interrupt for this single block */
552	
553	  dw_gdma_ll_channel_set_block_markers(dev, ch, true, true, true);
554	  dw_gdma_ll_channel_clear_intr(dev, ch, UINT32_MAX);
555	  dw_gdma_ll_channel_enable_intr_generation(dev, ch,
556	                             DW_GDMA_LL_CHANNEL_EVENT_BLOCK_TFR_DONE, true);
557	  dw_gdma_ll_channel_enable_intr_propagation(dev, ch,
558	                             DW_GDMA_LL_CHANNEL_EVENT_BLOCK_TFR_DONE, true);
559	
560	  /* Enable the channel */
561	
562	  dw_gdma_ll_channel_enable(dev, ch, true);
563	}
