565	/****************************************************************************
566	 * Name: esp_csi_dma_isr
567	 *
568	 * Description:
569	 *   DW-GDMA interrupt handler. On block-transfer-done for the CSI channel,
570	 *   invalidate the completed buffer's cache, notify the upper layer, and
571	 *   re-arm the DMA with the next buffer.
572	 ****************************************************************************/
573	
574	static int esp_csi_dma_isr(int irq, void *context, void *arg)
575	{
576	  dw_gdma_dev_t *dev = DW_GDMA_LL_GET_HW(0);
577	  const uint8_t ch = ESP_CSI_DMA_CHANNEL;
578	  uint32_t status;
579	
580	  /* --- Handle DSI channel 1 first (if it fired) --- */
581	
582	  {
583	    uint32_t dsi_st = dev->ch[1].int_st0.val;
584	    if (dsi_st)
585	      {
586	        extern void esp_dsi_dma_isr_handler(void);
587	        esp_dsi_dma_isr_handler();
588	      }
589	  }
590	
591	  /* --- Handle CSI channel 0 --- */
592	
593	  status = dev->ch[ch].int_st0.val;
594	
595	  if ((status & DW_GDMA_LL_CHANNEL_EVENT_BLOCK_TFR_DONE) == 0)
596	    {
597	      /* Not our event - clear whatever fired and return */
598	
599	      dw_gdma_ll_channel_clear_intr(dev, ch, status);
600	      return OK;
601	    }
602	
603	  dw_gdma_ll_channel_clear_intr(dev, ch, status);
604	
605	  g_csi_dev.frame_count++;
606	
607	  /* Invalidate cache for the just-filled buffer so the CPU sees DMA data */
608	
609	  if (g_csi_dev.dma_dst != NULL)
610	    {
611	      up_invalidate_dcache((uintptr_t)g_csi_dev.dma_dst,
612	                           (uintptr_t)g_csi_dev.dma_dst +
613	                           g_csi_dev.dma_dst_size);
614	    }
615	
616	  /* Notify upper layer and obtain the next destination buffer */
617	
618	  if (g_csi_dev.frame_cb != NULL)
619	    {
620	      FAR uint8_t *next = NULL;
621	      uint32_t next_size = 0;
622	
623	      g_csi_dev.frame_cb(g_csi_dev.frame_cb_arg, &next, &next_size);
624	
625	      if (next != NULL && next_size >= ESP_CSI_FRAME_SIZE)
626	        {
627	          g_csi_dev.dma_dst = next;
628	          g_csi_dev.dma_dst_size = next_size;
629	          esp_csi_dma_arm(next);
630	        }
631	      else
632	        {
633	          /* No buffer available: leave DMA disarmed until next start */
634	
635	          g_csi_dev.dma_dst = NULL;
636	        }
637	    }
638	
639	  return OK;
640	}
641	
642	/****************************************************************************
643	 * Name: esp_csi_dma_init
644	 *
645	 * Description:
646	 *   Initialize the DW-GDMA controller and allocate the CSI DMA channel
647	 *   interrupt. Also allocates internal backup frame buffers.
648	 ****************************************************************************/
649	
650	static int esp_csi_dma_init(void)
651	{
652	  dw_gdma_dev_t *dev = DW_GDMA_LL_GET_HW(0);
653	  int __DECLARE_RCC_ATOMIC_ENV;
654	  (void)__DECLARE_RCC_ATOMIC_ENV;
655	
656	  /* Allocate internal backup frame buffers (used when no v4l2 buffer is
657	   * queued). RAW8 sized, 64-byte (cache line) aligned.
658	   */
659	
660	  g_csi_dev.frame_buffer[0] = (uint8_t *)kmm_memalign(64,
661	                                                      ESP_CSI_FRAME_SIZE);
662	  g_csi_dev.frame_buffer[1] = (uint8_t *)kmm_memalign(64,
663	                                                      ESP_CSI_FRAME_SIZE);
664	  if (g_csi_dev.frame_buffer[0] == NULL || g_csi_dev.frame_buffer[1] == NULL)
665	    {
666	      syslog(LOG_ERR, "CSI: Failed to allocate frame buffers\n");
667	      return -ENOMEM;
668	    }
669	
670	  memset(g_csi_dev.frame_buffer[0], 0, ESP_CSI_FRAME_SIZE);
671	  memset(g_csi_dev.frame_buffer[1], 0, ESP_CSI_FRAME_SIZE);
672	  g_csi_dev.active_buf = 0;
673	
674	  /* Enable DW-GDMA bus clock and release reset */
675	
676	  dw_gdma_ll_enable_bus_clock(0, true);
677	  dw_gdma_ll_reset_register(0);
678	
679	  /* Reset and enable the controller, enable global interrupt */
680	
681	  dw_gdma_ll_reset(dev);
682	  dw_gdma_ll_enable_controller(dev, true);
683	  dw_gdma_ll_enable_intr_global(dev, true);
684	
685	  /* Hook the DW-GDMA interrupt */
686	
687	  g_csi_dev.cpuint = esp_setup_irq(ETS_DW_GDMA_INTR_SOURCE,
688	                                   ESP_IRQ_PRIORITY_DEFAULT,
689	                                   ESP_IRQ_TRIGGER_LEVEL,
690	                                   esp_csi_dma_isr, NULL);
691	  if (g_csi_dev.cpuint < 0)
692	    {
693	      syslog(LOG_ERR, "CSI: Failed to setup DW-GDMA IRQ: %d\n",
694	             g_csi_dev.cpuint);
695	      return g_csi_dev.cpuint;
696	    }
697	
698	  up_enable_irq(ESP_SOURCE2IRQ(ETS_DW_GDMA_INTR_SOURCE));
699	
700	  syslog(LOG_INFO, "CSI: DW-GDMA initialized (xfer_items=%d, frame=%d bytes)\n",
701	         ESP_CSI_DMA_XFER_ITEMS, ESP_CSI_FRAME_SIZE);
702	  return OK;
703	}
