766	/****************************************************************************
767	 * Name: esp_csi_start
768	 ****************************************************************************/
769	
770	int esp_csi_start(void)
771	{
772	  FAR uint8_t *dst;
773	  uint32_t size;
774	
775	  if (!g_csi_dev.initialized)
776	    {
777	      return -EINVAL;
778	    }
779	
780	  if (g_csi_dev.streaming)
781	    {
782	      return OK;
783	    }
784	
785	  /* Choose the initial DMA destination: a buffer set via esp_csi_set_buffer
786	   * if available, otherwise the internal backup buffer.
787	   */
788	
789	  if (g_csi_dev.dma_dst != NULL &&
790	      g_csi_dev.dma_dst_size >= ESP_CSI_FRAME_SIZE)
791	    {
792	      dst  = g_csi_dev.dma_dst;
793	      size = g_csi_dev.dma_dst_size;
794	    }
795	  else
796	    {
797	      dst  = g_csi_dev.frame_buffer[0];
798	      size = ESP_CSI_FRAME_SIZE;
799	    }
800	
801	  g_csi_dev.dma_dst = dst;
802	  g_csi_dev.dma_dst_size = size;
803	
804	  /* Arm the DMA before enabling the bridge so the first frame is captured */
805	
806	  esp_csi_dma_arm(dst);
807	
808	  /* Enable CSI Bridge (csi_en register) to start receiving data */
809	
810	  mipi_csi_brg_ll_enable(MIPI_CSI_BRG_LL_GET_HW(0), true);
811	
812	  g_csi_dev.streaming = true;
813	  syslog(LOG_INFO, "CSI: Streaming started (dst=%p)\n", dst);
814	  return OK;
815	}
816	
817	/****************************************************************************
818	 * Name: esp_csi_stop
819	 ****************************************************************************/
820	
821	int esp_csi_stop(void)
822	{
823	  if (!g_csi_dev.initialized)
824	    {
825	      return -EINVAL;
826	    }
827	
828	  if (!g_csi_dev.streaming)
829	    {
830	      return OK;
831	    }
832	
833	  /* Disable CSI Bridge (csi_en register) */
834	
835	  mipi_csi_brg_ll_enable(MIPI_CSI_BRG_LL_GET_HW(0), false);
836	
837	  /* Disable the DMA channel */
838	
839	  dw_gdma_ll_channel_enable(DW_GDMA_LL_GET_HW(0), ESP_CSI_DMA_CHANNEL, false);
840	
841	  g_csi_dev.streaming = false;
842	  syslog(LOG_INFO, "CSI: Streaming stopped (%lu frames)\n",
843	         (unsigned long)g_csi_dev.frame_count);
844	  return OK;
845	}
