820	 * Name: esp_mipi_dsi_initialize
821	 *
822	 * Description:
823	 *   Full DSI initialization sequence for EK79007 panel.
824	 *
825	 ****************************************************************************/
826	
827	int esp_mipi_dsi_initialize(void)
828	{
829	  int ret;
830	
831	  syslog(LOG_INFO, "[DSI] === MIPI-DSI init START ===\n");
832	
833	  /* Phase 1: Enable PHY LDO and clocks */
834	
835	  dsi_enable_phy_ldo();
836	  dsi_enable_clocks();
837	
838	  /* Phase 2: Initialize PHY (Steps 4-6) */
839	
840	  ret = dsi_init_phy();
841	  if (ret < 0)
842	    {
843	      return ret;
844	    }
845	
846	
847	  /* Phase 3: Configure Host for command mode (Steps 7-12) */
848	
849	  dsi_configure_host();
850	
851	  /* Phase 4: Reset panel and send DCS commands */
852	
853	  dsi_reset_panel();
854	  dsi_send_panel_commands();
855	
856	  /* Phase 5: Configure DPI / Video mode (Steps 14-17) */
857	
858	  dsi_configure_dpi();
859	
860	  /* Phase 6: Allocate framebuffer */
861	
862	  ret = dsi_alloc_framebuffer();
863	  if (ret < 0)
864	    {
865	      return ret;
866	    }
867	
868	
869	  /* Phase 7: Start video output (Steps 20-21) */
870	
871	  dsi_start_video();
872	
873	  /* Write initial framebuffer content to bridge */
874	
875	
876	  /* Start continuous framebuffer refresh via DMA.
877	   * EK79007AD requires: HS Video Pattern started BEFORE backlight.
878	   * DMA will continuously feed bridge FIFO from framebuffer.
879	   */
880	
881	  /* DMA refresh disabled (causes hang during bringup).
882	   * Use CPU refresh thread instead.
883	   */
884	
885	  /* Wait 200ms for AVDD to stabilize before enabling backlight
886	   * (per EK79007AD datasheet power-on sequence)
887	   */
888	
889	  dsi_delay_ms(200);
890	
891	  /* Enable backlight */
892	
893	  dsi_enable_backlight();
894	
895	  syslog(LOG_INFO, "[DSI] === MIPI-DSI init COMPLETE ===\n");
896	
897	  /* Note: Continuous refresh not started here.
898	   * The fb0 pandisplay ioctl will call esp_mipi_dsi_flush_fb()
899	   * when nxcamera/apps write to the framebuffer.
900	   */
901	
902	  return OK;
903	}
