16	#include "hal/mipi_dsi_hal.h"
17	#include "esp_cache.h"
18	
19	/* GPIO register-direct access (proven working from previous code) */
20	
21	#define GPIO_BASE         0x500E0000
22	#define IO_MUX_BASE       0x500E1000
23	#define GPIO_OUT_W1TS     (*(volatile uint32_t *)(GPIO_BASE + 0x08))
24	#define GPIO_OUT_W1TC     (*(volatile uint32_t *)(GPIO_BASE + 0x0C))
25	#define GPIO_ENABLE_W1TS  (*(volatile uint32_t *)(GPIO_BASE + 0x24))
26	
27	/* PMU LDO for DSI PHY (2.5V, proven working) */
28	
29	#define PMU_EXT_LDO_CTRL  (*(volatile uint32_t *)0x501151C0)
30	#define PMU_EXT_LDO_ANA   (*(volatile uint32_t *)0x501151C4)
31	
32	static esp_lcd_dsi_bus_handle_t g_dsi_bus;
33	static esp_lcd_dpi_panel_handle_t g_dpi_panel;
34	
35	/****************************************************************************
36	 * Private Functions
37	 ****************************************************************************/
38	
39	static void dsi_phy_ldo_enable(void)
40	{
41	  /* LDO channel 3 -> 2.5V: dref=13, mul=3 */
42	
43	  PMU_EXT_LDO_ANA = (13u << 28) | (3u << 23);
44	  PMU_EXT_LDO_CTRL = (1u << 7) | (1u << 8); /* force_tieh_sel + xpd */
45	  usleep(5000); /* Wait for LDO to stabilize */
46	}
47	
48	static void gpio_set_output(uint32_t pin)
49	{
50	  volatile uint32_t *iomux = (volatile uint32_t *)
51	      (IO_MUX_BASE + 0x04 + pin * 4);
52	  *iomux = (1u << 12); /* func_sel=1 (GPIO function) */
53	  GPIO_ENABLE_W1TS = (1u << pin);
54	}
55	
56	static void panel_reset(void)
57	{
58	  gpio_set_output(27);
59	
60	  /* Reset pulse: low 10ms -> high 85ms (meets EK79007 timing) */
61	
62	  GPIO_OUT_W1TC = (1u << 27);
63	  usleep(10000);
64	  GPIO_OUT_W1TS = (1u << 27);
65	  usleep(85000);
66	}
67	
68	static void panel_send_dcs(mipi_dsi_hal_context_t *hal)
69	{
70	  static const struct
71	  {
72	    uint8_t cmd;
73	    uint8_t data;
74	  } init_cmds[] =
75	    {
76	      { 0xb2, 0x10 },
77	      { 0x80, 0x8b },
78	      { 0x81, 0x78 },
79	      { 0x82, 0x84 },
80	      { 0x83, 0x88 },
81	      { 0x84, 0xa8 },
82	      { 0x85, 0xe3 },
83	      { 0x86, 0x88 },
84	    };
85	
86	  for (size_t i = 0; i < sizeof(init_cmds) / sizeof(init_cmds[0]); i++)
87	    {
88	      mipi_dsi_hal_host_gen_write_dcs_command(hal, 0, init_cmds[i].cmd,
89	                                              1, &init_cmds[i].data, 1);
90	    }
91	
92	  mipi_dsi_hal_host_gen_write_dcs_command(hal, 0, 0x11, 1, NULL, 0);
93	  usleep(120000); /* 120ms required by spec */
94	}
95	
96	static void backlight_enable(void)
97	{
98	  gpio_set_output(26);
99	  GPIO_OUT_W1TS = (1u << 26);
100	}
101	
102	/****************************************************************************
103	 * Public Functions
104	 ****************************************************************************/
105	
106	int esp_dsi_fb_initialize(void)
107	{
108	  int ret;
109	
110	  syslog(LOG_INFO, "[DSI-FB] Starting initialization\n");
111	
112	  /* 1. PHY LDO (2.5V) */
113	
114	  dsi_phy_ldo_enable();
115	  syslog(LOG_INFO, "[DSI-FB] PHY LDO enabled\n");
116	
117	  /* 2. DSI Bus (PHY + Host) */
118	
119	  esp_lcd_dsi_bus_config_t bus_cfg;
120	  memset(&bus_cfg, 0, sizeof(bus_cfg));
121	  bus_cfg.bus_id = 0;
122	  bus_cfg.num_data_lanes = 2;
123	  bus_cfg.lane_bit_rate_mbps = 1000.0f;
124	  bus_cfg.phy_clk_src = 0; /* default XTAL */
125	  bus_cfg.flags.clock_lane_force_hs = false;
126	
127	  ret = esp_lcd_new_dsi_bus(&bus_cfg, &g_dsi_bus);
128	  if (ret != 0)
129	    {
130	      syslog(LOG_ERR, "[DSI-FB] Bus init failed: %d\n", ret);
131	      return ret;
132	    }
133	
134	  syslog(LOG_INFO, "[DSI-FB] Bus init OK\n");
135	
136	  /* 3. Panel reset + DCS commands (while in command mode) */
137	
138	  panel_reset();
139	  panel_send_dcs(&g_dsi_bus->hal);
140	  syslog(LOG_INFO, "[DSI-FB] Panel reset + Sleep Out done\n");
141	
142	  /* 4. DPI Panel (Bridge + DMA link) */
143	
144	  esp_lcd_dpi_panel_config_t dpi_cfg;
145	  memset(&dpi_cfg, 0, sizeof(dpi_cfg));
146	  dpi_cfg.virtual_channel = 0;
147	  dpi_cfg.dpi_clock_freq_mhz = 52.0f;
148	  dpi_cfg.video_timing.h_size = 1024;
149	  dpi_cfg.video_timing.v_size = 600;
150	  dpi_cfg.video_timing.hsync_pulse_width = 10;
151	  dpi_cfg.video_timing.hsync_back_porch = 120;
152	  dpi_cfg.video_timing.hsync_front_porch = 120;
153	  dpi_cfg.video_timing.vsync_pulse_width = 1;
154	  dpi_cfg.video_timing.vsync_back_porch = 20;
155	  dpi_cfg.video_timing.vsync_front_porch = 10;
156	
157	  ret = esp_lcd_new_panel_dpi(g_dsi_bus, &dpi_cfg, &g_dpi_panel);
158	  if (ret != 0)
159	    {
160	      syslog(LOG_ERR, "[DSI-FB] DPI panel create failed: %d\n", ret);
161	      return ret;
162	    }
163	
164	  /* 5. DMA start + video mode will be called AFTER Camera init
165	   * (Camera's esp_csi_dma_init resets GDMA, which would erase our config)
166	   */
167	
168	  syslog(LOG_INFO, "[DSI-FB] Phase 1 done (bus+panel created). "
169	         "Call esp_dsi_fb_start_refresh() after camera init.\n");
170	
171	  return 0;
172	}
173	
174	/****************************************************************************
175	 * Name: esp_dsi_fb_start_refresh
176	 *
177	 * Description:
178	 *   Start DMA refresh loop + video mode + backlight.
179	 *   MUST be called AFTER Camera CSI init (which resets GDMA).
180	 ****************************************************************************/
181	
182	int esp_dsi_fb_start_refresh(void)
183	{
184	  int ret;
185	
186	  if (g_dpi_panel == NULL)
187	    {
188	      return -EINVAL;
189	    }
190	
191	  /* Fill framebuffer with white for visual verification */
192	
193	  {
194	    uint8_t *fb = esp_lcd_dpi_panel_get_fb(g_dpi_panel);
195	    size_t fb_size = esp_lcd_dpi_panel_get_fb_size(g_dpi_panel);
196	    if (fb && fb_size > 0)
197	      {
198	        memset(fb, 0xFF, fb_size);  /* White = 0xFF for all RGB888 bytes */
199	        esp_cache_msync(fb, fb_size, ESP_CACHE_MSYNC_FLAG_DIR_C2M);
200	        syslog(LOG_INFO, "[DSI-FB] FB filled white (%zu bytes)\n", fb_size);
201	      }
202	  }
203	
204	  /* Start DMA -> video mode -> DPI output */
205	
206	  ret = esp_lcd_dpi_panel_init(g_dpi_panel);
207	  if (ret != 0)
208	    {
209	      syslog(LOG_ERR, "[DSI-FB] DPI panel init failed: %d\n", ret);
210	      return ret;
211	    }
212	
213	  /* Wait 200ms for stable video, then backlight */
214	
215	  usleep(200000);
216	  backlight_enable();
217	  syslog(LOG_INFO, "[DSI-FB] Backlight ON, display ready\n");
218	
219	  return 0;
220	}
221	
222	uint8_t *esp_dsi_fb_get_buffer(void)
223	{
224	  if (g_dpi_panel == NULL)
225	    {
226	      return NULL;
227	    }
228	
229	  return esp_lcd_dpi_panel_get_fb(g_dpi_panel);
230	}
