49	/****************************************************************************
50	 * Pre-processor Definitions
51	 ****************************************************************************/
52	
53	#define MIPI_DSI_BRG_MEM_BASE  0x50105000  /* Bridge FIFO address */
54	#define DPI_PANEL_FB_BPP       24          /* RGB888: 3 bytes per pixel */
55	#define DPI_CLK_SRC_MHZ        240         /* PLL_F240M */
56	
57	/* Color format — use HAL's lcd_color_format_t enum from lcd_types.h.
58	 * Do NOT redefine LCD_COLOR_FMT_RGB888 — it's a FOURCC code, not 5.
59	 */
60	
61	/****************************************************************************
62	 * Private Types
63	 ****************************************************************************/
64	
65	struct esp_lcd_dpi_panel_t
66	{
67	  esp_lcd_dsi_bus_handle_t    bus;
68	  dw_gdma_channel_handle_t   dma_chan;
69	  dw_gdma_link_list_handle_t link_list;
70	  uint8_t                    *fb;
71	  size_t                      fb_size;
72	  uint32_t                    h_pixels;
73	  uint32_t                    v_pixels;
74	  uint32_t                    bits_per_pixel;
75	  dw_gdma_block_transfer_config_t xfer;
76	};
77	
78	/****************************************************************************
79	 * Private Data
80	 ****************************************************************************/
81	
82	/* Static panel instance — only one DPI panel on ESP32-P4 */
83	
84	static struct esp_lcd_dpi_panel_t g_dpi_panel;
