86	/****************************************************************************
87	 * Private Functions
88	 ****************************************************************************/
89	
90	static bool dsi_dma_trans_done_cb(dw_gdma_channel_handle_t chan,
91	                                  const dw_gdma_trans_done_event_data_t *event_data,
92	                                  void *user_data)
93	{
94	  struct esp_lcd_dpi_panel_t *panel = user_data;
95	  dw_gdma_link_list_item_t *lli;
96	  dw_gdma_block_markers_t m;
97	
98	  (void)event_data;
99	
100	  if (!panel)
101	    {
102	      return false;
103	    }
104	
105	  lli = dw_gdma_link_list_get_item(panel->link_list, 0);
106	  dw_gdma_lli_config_transfer(lli, &panel->xfer);
107	  m.is_valid = true;
108	  m.is_last  = true;
109	  dw_gdma_lli_set_block_markers(lli, m);
110	  dw_gdma_channel_use_link_list(chan, panel->link_list);
111	  dw_gdma_channel_enable_ctrl(chan, true);
112	  return false;
113	}
