115	/****************************************************************************
116	 * Public Functions
117	 ****************************************************************************/
118	
119	/****************************************************************************
120	 * Name: esp_lcd_new_panel_dpi
121	 ****************************************************************************/
122	
123	int esp_lcd_new_panel_dpi(esp_lcd_dsi_bus_handle_t bus,
124	                          const esp_lcd_dpi_panel_config_t *config,
125	                          esp_lcd_dpi_panel_handle_t *ret_panel)
126	{
127	  struct esp_lcd_dpi_panel_t *panel = &g_dpi_panel;
128	  uint32_t h_pixels;
129	  uint32_t v_pixels;
130	  uint32_t dpi_div;
131	  int ret;
132	
133	  if (!bus || !config || !ret_panel)
134	    {
135	      return -EINVAL;
136	    }
137	
138	  memset(panel, 0, sizeof(*panel));
139	
140	  /* Store bus reference and pixel dimensions */
141	
142	  panel->bus            = bus;
143	  panel->bits_per_pixel = DPI_PANEL_FB_BPP;
144	  h_pixels              = config->video_timing.h_size;
145	  v_pixels              = config->video_timing.v_size;
146	  panel->h_pixels       = h_pixels;
147	  panel->v_pixels       = v_pixels;
148	
149	  /* Compute framebuffer size: h * v * 3 bytes (RGB888) */
150	
151	  panel->fb_size = (size_t)h_pixels * v_pixels * (DPI_PANEL_FB_BPP / 8);
152	
153	  /* Allocate framebuffer — 64-byte aligned for cache line */
154	
155	  panel->fb = (uint8_t *)kmm_memalign(64, panel->fb_size);
156	  if (!panel->fb)
157	    {
158	      syslog(LOG_ERR, "[DPI] Failed to allocate FB (%zu bytes)\n",
159	             panel->fb_size);
160	      return -ENOMEM;
161	    }
162	
163	  memset(panel->fb, 0, panel->fb_size);
164	
165	  /* Flush zeros to physical memory (cache writeback) */
166	
167	  esp_cache_msync(panel->fb, panel->fb_size,
168	                  ESP_CACHE_MSYNC_FLAG_DIR_C2M);
169	
170	  /* Configure DPI clock divider from PLL_F240M */
171	
172	  dpi_div = mipi_dsi_hal_host_dpi_calculate_divider(
173	      &bus->hal, (float)DPI_CLK_SRC_MHZ, config->dpi_clock_freq_mhz);
174	
175	  PERIPH_RCC_ATOMIC()
176	  {
177	    mipi_dsi_ll_set_dpi_clock_source(bus->bus_id,
178	                                     MIPI_DSI_DPI_CLK_SRC_PLL_F240M);
179	    mipi_dsi_ll_set_dpi_clock_div(bus->bus_id, dpi_div);
180	    mipi_dsi_ll_enable_dpi_clock(bus->bus_id, true);
181	  }
182	
183	  /* Configure Host DPI parameters */
184	
185	  mipi_dsi_host_ll_dpi_set_vcid(bus->hal.host,
186	                                config->virtual_channel);
187	  mipi_dsi_host_ll_dpi_set_color_coding(bus->hal.host,
188	                                        LCD_COLOR_FMT_RGB888, 0);
189	
190	  /* Timing signal polarities: all active low */
191	
192	  mipi_dsi_host_ll_dpi_set_timing_polarity(bus->hal.host,
193	                                           false, false,
194	                                           false, false, false);
195	
196	  /* Enable low-power transitions during blanking periods */
197	
198	  mipi_dsi_host_ll_dpi_enable_lp_horizontal_timing(bus->hal.host,
199	                                                   true, true);
200	  mipi_dsi_host_ll_dpi_enable_lp_vertical_timing(bus->hal.host,
201	                                                 true, true,
202	                                                 true, true);
203	
204	  /* Commands transmitted in low-power mode */
205	
206	  mipi_dsi_host_ll_dpi_enable_lp_command(bus->hal.host, true);
207	
208	  /* Enable frame ACK from panel */
209	
210	  mipi_dsi_host_ll_dpi_enable_frame_ack(bus->hal.host, true);
211	
212	  /* Video mode: burst with sync pulses (energy-efficient) */
213	
214	  mipi_dsi_host_ll_dpi_set_video_burst_type(bus->hal.host,
215	      MIPI_DSI_LL_VIDEO_BURST_WITH_SYNC_PULSES);
216	
217	  /* Active line pixel count */
218	
219	  mipi_dsi_host_ll_dpi_set_video_packet_pixel_num(bus->hal.host,
220	                                                  h_pixels);
221	
222	  /* Disable multi-packets and null packets */
223	
224	  mipi_dsi_host_ll_dpi_set_trunks_num(bus->hal.host, 0);
225	  mipi_dsi_host_ll_dpi_set_null_packet_size(bus->hal.host, 0);
226	
227	  /* Set horizontal timing */
228	
229	  mipi_dsi_hal_host_dpi_set_horizontal_timing(&bus->hal,
230	      config->video_timing.hsync_pulse_width,
231	      config->video_timing.hsync_back_porch,
232	      config->video_timing.h_size,
233	      config->video_timing.hsync_front_porch);
234	
235	  /* Set vertical timing */
236	
237	  mipi_dsi_hal_host_dpi_set_vertical_timing(&bus->hal,
238	      config->video_timing.vsync_pulse_width,
239	      config->video_timing.vsync_back_porch,
240	      config->video_timing.v_size,
241	      config->video_timing.vsync_front_porch);
242	
243	  /* Configure Bridge */
244	
245	  mipi_dsi_brg_ll_set_num_pixel_bits(bus->hal.bridge,
246	      h_pixels * v_pixels * DPI_PANEL_FB_BPP);
247	  mipi_dsi_brg_ll_set_underrun_discard_count(bus->hal.bridge,
248	      h_pixels);
249	  mipi_dsi_brg_ll_set_input_color_format(bus->hal.bridge,
250	      LCD_COLOR_FMT_RGB888);
251	  mipi_dsi_brg_ll_set_output_color_format(bus->hal.bridge,
252	      LCD_COLOR_FMT_RGB888, 0);
253	  mipi_dsi_brg_ll_set_flow_controller(bus->hal.bridge,
254	      MIPI_DSI_LL_FLOW_CONTROLLER_DMA);
255	  mipi_dsi_brg_ll_set_multi_block_number(bus->hal.bridge, 1);
256	  mipi_dsi_brg_ll_set_burst_len(bus->hal.bridge, 256);
257	  mipi_dsi_brg_ll_set_empty_threshold(bus->hal.bridge, 1024 - 256);
258	
259	  /* Enable DSI bridge */
260	
261	  mipi_dsi_brg_ll_enable(bus->hal.bridge, true);
262	  mipi_dsi_brg_ll_update_dpi_config(bus->hal.bridge);
263	
264	  /* DMA channel will be created in esp_lcd_dpi_panel_init() —
265	   * AFTER Camera CSI init (which resets GDMA and clears all channels).
266	   */
267	
268	  *ret_panel = panel;
269	
270	  syslog(LOG_INFO,
271	         "[DPI] Panel created: %lux%lu, fb=%p (%zu bytes)\n",
272	         (unsigned long)h_pixels, (unsigned long)v_pixels,
273	         panel->fb, panel->fb_size);
274	
275	  return 0;
276	}
277	
278	/****************************************************************************
279	 * Name: esp_lcd_dpi_panel_init
280	 *
281	 * Description:
282	 *   Start the DPI panel refresh loop.
283	 *   Critical sequence: start DMA → enable video mode → enable DPI output.
284	 ****************************************************************************/
285	
286	int esp_lcd_dpi_panel_init(esp_lcd_dpi_panel_handle_t panel)
287	{
288	  dw_gdma_block_transfer_config_t xfer;
289	  int ret;
290	
291	  if (!panel || !panel->fb)
292	    {
293	      return -EINVAL;
294	    }
295	
296	  /* Create DMA channel (must be done AFTER Camera CSI init which
297	   * resets GDMA and clears all channel configurations).
298	   */
299	
300	  dw_gdma_channel_alloc_config_t dma_cfg;
301	  memset(&dma_cfg, 0, sizeof(dma_cfg));
302	
303	  dma_cfg.src.block_transfer_type      = DW_GDMA_BLOCK_TRANSFER_LIST;
304	  dma_cfg.src.role                     = DW_GDMA_ROLE_MEM;
305	  dma_cfg.src.handshake_type           = DW_GDMA_HANDSHAKE_HW;
306	  dma_cfg.src.num_outstanding_requests = 5;
307	
308	  dma_cfg.dst.block_transfer_type      = DW_GDMA_BLOCK_TRANSFER_LIST;
309	  dma_cfg.dst.role                     = DW_GDMA_ROLE_PERIPH_DSI;
310	  dma_cfg.dst.handshake_type           = DW_GDMA_HANDSHAKE_HW;
311	  dma_cfg.dst.num_outstanding_requests = 2;
312	
313	  dma_cfg.flow_controller              = DW_GDMA_FLOW_CTRL_SELF;
314	  dma_cfg.chan_priority                 = 1;
315	
316	  ret = dw_gdma_new_channel(&dma_cfg, &panel->dma_chan);
317	  if (ret < 0)
318	    {
319	      syslog(LOG_ERR, "[DPI] Failed to create DMA channel: %d\n", ret);
320	      return ret;
321	    }
322	
323	  /* Create DMA link list (1 item, self-cycling) */
324	
325	  dw_gdma_link_list_config_t ll_cfg;
326	  memset(&ll_cfg, 0, sizeof(ll_cfg));
327	  ll_cfg.num_items = 1;
328	
329	  ret = dw_gdma_new_link_list(&ll_cfg, &panel->link_list);
330	  if (ret < 0)
331	    {
332	      syslog(LOG_ERR, "[DPI] Failed to create link list: %d\n", ret);
333	      return ret;
334	    }
335	
336	  /* Register DMA callback for continuous re-arm */
337	
338	  {
339	    dw_gdma_event_callbacks_t cbs;
340	
341	    memset(&cbs, 0, sizeof(cbs));
342	    cbs.on_block_trans_done = dsi_dma_trans_done_cb;
343	    ret = dw_gdma_channel_register_event_callbacks(panel->dma_chan, &cbs,
344	                                                   panel);
345	    if (ret < 0)
346	      {
347	        syslog(LOG_ERR, "[DPI] Failed to register DMA callbacks: %d\n", ret);
348	        return ret;
349	      }
350	  }
351	
352	  /* Configure DMA transfer parameters in the LLI:
353	   *   Source: framebuffer in PSRAM/SRAM (incrementing)
354	   *   Dest:   Bridge FIFO at fixed address
355	   */
356	
357	  memset(&xfer, 0, sizeof(xfer));
358	
359	  xfer.src.addr       = (uint32_t)(uintptr_t)panel->fb;
360	  xfer.src.burst_mode = DW_GDMA_BURST_MODE_INCREMENT;

293	int kthread_create(FAR const char *name, int priority,
294	                   int stack_size, main_t entry, FAR char * const argv[])
295	{
296	  return kthread_create_with_stack(name, priority,
297	                                   NULL, stack_size, entry, argv);
298	}
