1	/****************************************************************************
2	 * arch/risc-v/src/esp32p4/esp_dsi_fb.c
3	 *
4	 * SPDX-License-Identifier: Apache-2.0
5	 ****************************************************************************/
6	
7	#include <nuttx/config.h>
8	#include <unistd.h>
9	#include <string.h>
10	#include <errno.h>
11	#include <syslog.h>
12	#include <nuttx/kthread.h>
13	
14	#include "esp_dsi_fb.h"
15	#include "esp_lcd_dsi_bus_nuttx.h"
16	#include "esp_lcd_panel_dpi_nuttx.h"
17	#include "hal/mipi_dsi_hal.h"
18	#include "esp_cache.h"
19	
20	/* GPIO register-direct access (proven working from previous code) */
21	
22	#define GPIO_BASE         0x500E0000
23	#define IO_MUX_BASE       0x500E1000
24	#define GPIO_OUT_W1TS     (*(volatile uint32_t *)(GPIO_BASE + 0x08))
25	#define GPIO_OUT_W1TC     (*(volatile uint32_t *)(GPIO_BASE + 0x0C))
26	#define GPIO_ENABLE_W1TS  (*(volatile uint32_t *)(GPIO_BASE + 0x24))
27	
28	/* PMU LDO for DSI PHY (2.5V, proven working) */
29	
30	#define PMU_EXT_LDO_CTRL  (*(volatile uint32_t *)0x501151C0)
31	#define PMU_EXT_LDO_ANA   (*(volatile uint32_t *)0x501151C4)
32	
33	static esp_lcd_dsi_bus_handle_t g_dsi_bus;
34	static esp_lcd_dpi_panel_handle_t g_dpi_panel;
35	
36	/****************************************************************************
37	 * Private Functions
38	 ****************************************************************************/
39	
40	static void dsi_phy_ldo_enable(void)
41	{
42	  /* LDO channel 3 -> 2.5V: dref=13, mul=3 */
43	
44	  PMU_EXT_LDO_ANA = (13u << 28) | (3u << 23);
45	  PMU_EXT_LDO_CTRL = (1u << 7) | (1u << 8); /* force_tieh_sel + xpd */
46	  usleep(5000); /* Wait for LDO to stabilize */
47	}
48	
49	static void gpio_set_output(uint32_t pin)
50	{
51	  volatile uint32_t *iomux = (volatile uint32_t *)
52	      (IO_MUX_BASE + 0x04 + pin * 4);
53	  *iomux = (1u << 12); /* func_sel=1 (GPIO function) */
54	  GPIO_ENABLE_W1TS = (1u << pin);
55	}
56	
57	static void panel_reset(void)
58	{
59	  gpio_set_output(27);
60	
61	  /* Reset pulse: low 10ms -> high 85ms (meets EK79007 timing) */
62	
63	  GPIO_OUT_W1TC = (1u << 27);
64	  usleep(10000);
65	  GPIO_OUT_W1TS = (1u << 27);
66	  usleep(85000);
67	}
68	
69	static void panel_send_dcs(mipi_dsi_hal_context_t *hal)
70	{
71	  static const struct
72	  {
73	    uint8_t cmd;
74	    uint8_t data;
75	  } init_cmds[] =
76	    {
77	      { 0xb2, 0x10 },
78	      { 0x80, 0x8b },
79	      { 0x81, 0x78 },
80	      { 0x82, 0x84 },
81	      { 0x83, 0x88 },
82	      { 0x84, 0xa8 },
83	      { 0x85, 0xe3 },
84	      { 0x86, 0x88 },
85	    };
86	
87	  for (size_t i = 0; i < sizeof(init_cmds) / sizeof(init_cmds[0]); i++)
88	    {
89	      mipi_dsi_hal_host_gen_write_dcs_command(hal, 0, init_cmds[i].cmd,
90	                                              1, &init_cmds[i].data, 1);
91	    }
92	
93	  mipi_dsi_hal_host_gen_write_dcs_command(hal, 0, 0x11, 1, NULL, 0);
94	  usleep(120000); /* 120ms required by spec */
95	}
96	
97	static void backlight_enable(void)
98	{
99	  gpio_set_output(26);
100	  GPIO_OUT_W1TS = (1u << 26);
101	}
102	
103	/****************************************************************************
104	 * Public Functions
105	 ****************************************************************************/
106	
107	int esp_dsi_fb_initialize(void)
108	{
109	  int ret;
110	
111	  syslog(LOG_INFO, "[DSI-FB] Starting initialization\n");
112	
113	  /* 1. PHY LDO (2.5V) */
114	
115	  dsi_phy_ldo_enable();
116	  syslog(LOG_INFO, "[DSI-FB] PHY LDO enabled\n");
117	
118	  /* 2. DSI Bus (PHY + Host) */
119	
120	  esp_lcd_dsi_bus_config_t bus_cfg;
121	  memset(&bus_cfg, 0, sizeof(bus_cfg));
122	  bus_cfg.bus_id = 0;
123	  bus_cfg.num_data_lanes = 2;
124	  bus_cfg.lane_bit_rate_mbps = 1000.0f;
125	  bus_cfg.phy_clk_src = 0; /* default XTAL */
126	  bus_cfg.flags.clock_lane_force_hs = false;
127	
128	  ret = esp_lcd_new_dsi_bus(&bus_cfg, &g_dsi_bus);
129	  if (ret != 0)
130	    {
131	      syslog(LOG_ERR, "[DSI-FB] Bus init failed: %d\n", ret);
132	      return ret;
133	    }
134	
135	  syslog(LOG_INFO, "[DSI-FB] Bus init OK\n");
136	
137	  /* 3. Panel reset + DCS commands (while in command mode) */
138	
139	  panel_reset();
140	  panel_send_dcs(&g_dsi_bus->hal);
141	  syslog(LOG_INFO, "[DSI-FB] Panel reset + Sleep Out done\n");
142	
143	  /* 4. DPI Panel (Bridge + DMA link) */
144	
145	  esp_lcd_dpi_panel_config_t dpi_cfg;
146	  memset(&dpi_cfg, 0, sizeof(dpi_cfg));
147	  dpi_cfg.virtual_channel = 0;
148	  dpi_cfg.dpi_clock_freq_mhz = 52.0f;
149	  dpi_cfg.video_timing.h_size = 1024;
150	  dpi_cfg.video_timing.v_size = 600;
151	  dpi_cfg.video_timing.hsync_pulse_width = 10;
152	  dpi_cfg.video_timing.hsync_back_porch = 120;
153	  dpi_cfg.video_timing.hsync_front_porch = 120;
154	  dpi_cfg.video_timing.vsync_pulse_width = 1;
155	  dpi_cfg.video_timing.vsync_back_porch = 20;
156	  dpi_cfg.video_timing.vsync_front_porch = 10;
157	
158	  ret = esp_lcd_new_panel_dpi(g_dsi_bus, &dpi_cfg, &g_dpi_panel);
159	  if (ret != 0)
160	    {
161	      syslog(LOG_ERR, "[DSI-FB] DPI panel create failed: %d\n", ret);
162	      return ret;
163	    }
164	
165	  /* 5. DMA start + video mode will be called AFTER Camera init
166	   * (Camera's esp_csi_dma_init resets GDMA, which would erase our config)
167	   */
168	
169	  syslog(LOG_INFO, "[DSI-FB] Phase 1 done (bus+panel created). "
170	         "Call esp_dsi_fb_start_refresh() after camera init.\n");
171	
172	  return 0;
173	}
174	
175	/****************************************************************************
176	 * Name: esp_dsi_fb_start_refresh
177	 *
178	 * Description:
179	 *   Start DMA refresh loop + video mode + backlight.
180	 *   MUST be called AFTER Camera CSI init (which resets GDMA).
181	 ****************************************************************************/
182	
183	int esp_dsi_fb_start_refresh(void)
184	{
185	  int ret;
186	
187	  if (g_dpi_panel == NULL)
188	    {
189	      return -EINVAL;
190	    }
191	
192	  /* Fill framebuffer with white for visual verification */
193	
194	  {
195	    uint8_t *fb = esp_lcd_dpi_panel_get_fb(g_dpi_panel);
196	    size_t fb_size = esp_lcd_dpi_panel_get_fb_size(g_dpi_panel);
197	    if (fb && fb_size > 0)
198	      {
199	        memset(fb, 0xFF, fb_size);  /* White = 0xFF for all RGB888 bytes */
200	        esp_cache_msync(fb, fb_size, ESP_CACHE_MSYNC_FLAG_DIR_C2M);
201	        syslog(LOG_INFO, "[DSI-FB] FB filled white (%zu bytes)\n", fb_size);
202	      }
203	  }
204	
205	  /* Start DMA -> video mode -> DPI output */
206	
207	  ret = esp_lcd_dpi_panel_init(g_dpi_panel);
208	  if (ret != 0)
209	    {
210	      syslog(LOG_ERR, "[DSI-FB] DPI panel init failed: %d\n", ret);
211	      return ret;
212	    }
213	
214	  /* Wait 200ms for stable video, then backlight */
215	
216	  usleep(200000);
217	  backlight_enable();
218	  syslog(LOG_INFO, "[DSI-FB] Backlight ON, display ready\n");
219	
220	  return 0;
221	}
222	
223	uint8_t *esp_dsi_fb_get_buffer(void)
224	{
225	  if (g_dpi_panel == NULL)
226	    {
227	      return NULL;
228	    }
229	
230	  return esp_lcd_dpi_panel_get_fb(g_dpi_panel);
