static void backlight_enable(void)
{
  gpio_set_output(26);
  GPIO_OUT_W1TS = (1u << 26);
}

static void fill_framebuffer(uint8_t *fb, size_t fb_size,
                             uint8_t r, uint8_t g, uint8_t b)
{
  size_t i;

  if (fb == NULL || fb_size == 0)
    {
      return;
    }

  for (i = 0; i + 2 < fb_size; i += 3)
    {
      fb[i + 0] = r;
      fb[i + 1] = g;
      fb[i + 2] = b;
    }
}

static int esp_dsi_fb_demo_worker(int argc, FAR char *argv[])
{
  uint8_t *fb;
  size_t fb_size;
  bool show_red = true;

  (void)argc;
  (void)argv;

  fb = esp_lcd_dpi_panel_get_fb(g_dpi_panel);
  fb_size = esp_lcd_dpi_panel_get_fb_size(g_dpi_panel);
  if (fb == NULL || fb_size == 0)
    {
      syslog(LOG_ERR, "[DSI-FB] Demo thread: framebuffer unavailable\n");
      return -EINVAL;
    }

  while (1)
    {
      if (show_red)
        {
          fill_framebuffer(fb, fb_size, 0xff, 0x00, 0x00);
          syslog(LOG_INFO, "[DSI-FB] Demo color: red\n");
        }
      else
        {
          fill_framebuffer(fb, fb_size, 0x00, 0x00, 0xff);
          syslog(LOG_INFO, "[DSI-FB] Demo color: blue\n");
        }

      esp_cache_msync(fb, fb_size, ESP_CACHE_MSYNC_FLAG_DIR_C2M);
      show_red = !show_red;
      usleep(2000000);
    }

  return 0;
}

static int esp_dsi_fb_start_demo(void)
{
  if (g_demo_thread_pid > 0)
    {
      return 0;
    }

  g_demo_thread_pid = kthread_create("dsi_demo", 100,
                                     CONFIG_DEFAULT_TASK_STACKSIZE,
                                     esp_dsi_fb_demo_worker, NULL);
  if (g_demo_thread_pid < 0)
    {
      syslog(LOG_ERR, "[DSI-FB] Failed to start demo thread: %d\n",
             g_demo_thread_pid);
      return g_demo_thread_pid;
    }

  syslog(LOG_INFO, "[DSI-FB] Demo thread started (pid=%d)\n",
         g_demo_thread_pid);
  return 0;
}

