225	
226	int dw_gdma_new_link_list(const dw_gdma_link_list_config_t *config,
227	                          dw_gdma_link_list_handle_t *ret_list)
228	{
229	  struct dw_gdma_link_list_t *list;
230	  dw_gdma_link_list_item_t *items;
231	  dw_gdma_link_list_item_t *items_nc;
232	  size_t alloc_size;
233	
234	  if (config == NULL || ret_list == NULL || config->num_items == 0)
235	    {
236	      return -EINVAL;
237	    }
238	
239	  /* Allocate the list struct */
240	
241	  list = kmm_zalloc(sizeof(struct dw_gdma_link_list_t));
242	  if (list == NULL)
243	    {
244	      return -ENOMEM;
245	    }
246	
247	  /* Allocate LLI items with 64-byte alignment (required by HW) */
248	
249	  alloc_size = config->num_items * sizeof(dw_gdma_link_list_item_t);
250	  items = kmm_memalign(DW_GDMA_LL_LINK_LIST_ALIGNMENT, alloc_size);
251	  if (items == NULL)
252	    {
253	      kmm_free(list);
254	      return -ENOMEM;
255	    }
256	
257	  memset(items, 0, alloc_size);
258	
259	  /* Compute non-cached address for DMA to read */
260	
261	  items_nc = (dw_gdma_link_list_item_t *)DW_GDMA_NON_CACHE_ADDR(items);
262	
263	  /* For a single-item list, set up self-cycling (next points to self) */
264	
265	  if (config->num_items == 1)
266	    {
267	      dw_gdma_ll_lli_set_next_item_addr(items_nc, (uint32_t)items);
268	      dw_gdma_ll_lli_set_link_list_master_port(items_nc,
269	          DW_GDMA_LL_MASTER_PORT_MEMORY);
270	    }
271	  else
272	    {
273	      uint32_t i;
274	
275	      /* Chain items: each points to the next; last points to first */
276	
277	      for (i = 0; i < config->num_items; i++)
278	        {
279	          uint32_t next_idx = (i + 1) % config->num_items;
280	          dw_gdma_link_list_item_t *cur_nc = &items_nc[i];
281	          dw_gdma_link_list_item_t *next_cached =
282	              &items[next_idx];
283	
284	          dw_gdma_ll_lli_set_next_item_addr(cur_nc,
285	              (uint32_t)next_cached);
286	          dw_gdma_ll_lli_set_link_list_master_port(cur_nc,
287	              DW_GDMA_LL_MASTER_PORT_MEMORY);
288	        }
289	    }
290	
291	  list->num_items = config->num_items;
292	  list->items = items;
293	  list->items_nc = items_nc;
294	
295	  *ret_list = list;
296	  return 0;
297	}
