926	
927	  uint32_t ctl_lo = (1 << 0)  |  /* sms = master1 (memory) */
928	                    (0 << 2)  |  /* dms = master0 (DSI) */
929	                    (0 << 4)  |  /* sinc = increment */
930	                    (1 << 6)  |  /* dinc = fixed */
931	                    (3 << 8)  |  /* src_tr_width = 64-bit */
932	                    (3 << 11) |  /* dst_tr_width = 64-bit */
933	                    (8 << 14) |  /* src_msize = 512 items */
934	                    (7 << 18);   /* dst_msize = 256 items */
935	
936	  uint32_t ctl_hi = (1 << 6)  |  /* arlen_en */
937	                    (15 << 7) |  /* arlen = 16-1 */
938	                    (1 << 15) |  /* awlen_en */
939	                    (15 << 16)|  /* awlen = 16-1 */
940	                    (1 << 26) |  /* ioc_blktfr */
941	                    (1u << 31);  /* shadowreg_or_lli_valid=1, lli_last=0 (circular) */
942	
943	  /* Fill LLI structure via non-cached address for DMA coherency.
944	   * CPU writes go directly to memory, bypassing cache.
945	   * DMA reads the cached address (which maps to same physical memory).
946	   */
947	
948	  volatile struct dw_gdma_lli_s *lli_nc =
949	    (volatile struct dw_gdma_lli_s *)((uint32_t)&g_dma_lli + 0x40000000);
950	  lli_nc->sar_lo = (uint32_t)g_framebuffer;
951	  lli_nc->sar_hi = 0;
952	  lli_nc->dar_lo = MIPI_DSI_BRG_MEM_BASE;
953	  lli_nc->dar_hi = 0;
954	  lli_nc->block_ts = transfer_items - 1;
955	  lli_nc->reserved_14 = 0;
956	  lli_nc->llp_lo = LLI_DMA_ADDR;  /* Point to self (cached addr) for circular */
957	  lli_nc->llp_hi = 0;
958	  lli_nc->ctl_lo = ctl_lo;
959	  lli_nc->ctl_hi = ctl_hi;
960	  lli_nc->sstat = 0;
961	  lli_nc->dstat = 0;
962	  lli_nc->status_lo = 0;
963	  lli_nc->status_hi = 0;
964	  lli_nc->reserved_38 = 0;
965	  lli_nc->reserved_3c = 0;
966	
967	  /* Step 6: Configure channel registers for linked-list mode */
968	
969	  /* CFG0: src_multblk_type=3 (linked-list), dst_multblk_type=3 (linked-list) */
970	
971	  reg_write(DW_GDMA_CH0_BASE + CH_CFG0_OFF, (3 << 0) | (3 << 2));
972	
973	  /* CFG1: M2P, HW handshake for DSI, highest priority */
974	
975	  reg_write(DW_GDMA_CH0_BASE + CH_CFG1_OFF,
976	            (1 << 0)  |  /* tt_fc = M2P_DMAC */
977	            (1 << 3)  |  /* hs_sel_src = SW (memory side) */
978	            (0 << 4)  |  /* hs_sel_dst = HW (DSI bridge) */
979	            (0 << 12) |  /* dst_per = DSI (periph index 0) */
980	            (7 << 17));  /* ch_prior = 7 (highest) */
981	
982	  /* Step 7: Set LLP to point to our LLI (non-cached address) */
983	
984	  reg_write(DW_GDMA_CH0_BASE + CH_LLP0_OFF, LLI_DMA_ADDR);
985	  reg_write(DW_GDMA_CH0_BASE + CH_LLP1_OFF, 0);
986	
987	  /* Step 8: Clear pending interrupts and enable */
988	
989	  reg_write(DW_GDMA_CH0_BASE + CH_INTCLEAR0_OFF, 0xFFFFFFFF);
990	  reg_write(DW_GDMA_CH0_BASE + CH_INTSTATUS_ENA0_OFF, 0x03);
991	
992	  /* Step 9: Enable channel 0 (write-enable mode) */
993	
994	  reg_write(DW_GDMA_BASE + DMAC_CHEN0_OFF, (1 << 0) | (1 << 8));
995	
996	  syslog(LOG_INFO, "[DSI] DMA started (linked-list circular): fb=%p → DSI Bridge, %lu words\n",
997	         g_framebuffer, (unsigned long)transfer_items);
998	  syslog(LOG_INFO, "[DSI] LLI at %p (DMA addr: 0x%08lx)\n",
999	         &g_dma_lli, (unsigned long)LLI_DMA_ADDR);
1000	}
