555	static void phase3_host_config(void)
556	{
557	  syslog(LOG_INFO, "[DSI] Phase 3: Host config (command mode)\n");
558	
559	  /* 1. Enter command mode */
560	  reg_write(HOST_MODE_CFG, MODE_CFG_CMD_MODE);
561	
562	  /* 2. Set clock dividers */
563	  uint32_t clkmgr = (ESC_CLK_DIV & 0xFF) | ((TO_CLK_DIV & 0xFF) << 8);
564	  reg_write(HOST_CLKMGR_CFG, clkmgr);
565	
566	  /* 3. Set LP clock control: auto clock lane */
567	  reg_write(HOST_LPCLK_CTRL, AUTO_CLKLANE_CTRL);
568	
569	  /* 4. Set timeouts to 0 (disabled) */
570	  reg_write(HOST_TO_CNT_CFG, 0);
571	  reg_write(HOST_HS_RD_TO_CNT, 0);
572	  reg_write(HOST_LP_RD_TO_CNT, 0);
573	  reg_write(HOST_HS_WR_TO_CNT, 0);
574	  reg_write(HOST_LP_WR_TO_CNT, 0);
575	  reg_write(HOST_BTA_TO_CNT, 0);
576	
577	  /* 5. PHY timing config:
578	   * LP clock period: data_hs2lp=50, data_lp2hs=104
579	   * phy_tmr_lpclk_cfg: clk_hs2lp=46, clk_lp2hs=128
580	   */
581	  reg_write(HOST_PHY_TMR_CFG, (50 & 0x3FF) | ((104 & 0x3FF) << 16));
582	  reg_write(HOST_PHY_TMR_LPCLK_CFG, (46 & 0x3FF) | ((128 & 0x3FF) << 16));
583	
584	  /* 6. Enable CRC, ECC, EOTP */
585	  reg_write(HOST_PCKHDL_CFG, BTA_EN | CRC_RX_EN | ECC_RX_EN | EOTP_TX_EN);
586	
587	  /* 7. Set DPI virtual channel to 0 */
588	  reg_write(HOST_DPI_VCID, 0);
589	
590	  /* 8. Set generic interface virtual channel to 0 */
591	  reg_write(HOST_GEN_VCID, 0);
592	}
