610	static void phase4_panel_init(void)
611	{
612	  syslog(LOG_INFO, "[DSI] Phase 4: Panel init commands (EK79007)\n");
613	
614	  /* EK79007 initialization sequence via DCS:
615	   * 1. Configure 2 data lanes: cmd 0xB2, param 0x10
616	   * 2. Vendor specific registers
617	   * 3. Sleep Out command
618	   */
619	
620	  dsi_dcs_write_short(0xB2, 0x10, true);  /* 2-lane mode */
621	  dsi_dcs_write_short(0x80, 0x8B, true);
622	  dsi_dcs_write_short(0x81, 0x78, true);
623	  dsi_dcs_write_short(0x82, 0x84, true);
624	  dsi_dcs_write_short(0x83, 0x88, true);
625	  dsi_dcs_write_short(0x84, 0xA8, true);
626	  dsi_dcs_write_short(0x85, 0xE3, true);
627	  dsi_dcs_write_short(0x86, 0x88, true);
628	
629	  /* Sleep Out */
630	  dsi_dcs_write_short(0x11, 0x00, false);
631	  delay_ms(120);  /* Required delay after sleep out */
632	
633	  /* Display On */
634	  dsi_dcs_write_short(0x29, 0x00, false);
635	  delay_ms(20);
636	
637	  syslog(LOG_INFO, "[DSI] Panel init commands sent\n");
