640	static void phase5_dpi_config(void)
641	{
642	  syslog(LOG_INFO, "[DSI] Phase 5: DPI config\n");
643	
644	  /* Convert horizontal timings from DPI pixel clock to lane byte clock:
645	   * ratio = lane_byte_clk / dpi_clk = 125/48 ≈ 2.6
646	   * For integer math: multiply by 26 then divide by 10
647	   */
648	  uint32_t hsw_bytes = (ESP_DSI_HSYNC * DPI_TO_LANE_RATIO_X10 + 5) / 10;
649	  uint32_t hbp_bytes = (ESP_DSI_HBP * DPI_TO_LANE_RATIO_X10 + 5) / 10;
650	  uint32_t hline_bytes = ((ESP_DSI_HSYNC + ESP_DSI_HBP + ESP_DSI_HRES +
651	                           ESP_DSI_HFP) * DPI_TO_LANE_RATIO_X10 + 5) / 10;
652	
653	  /* Set color coding: RGB565 = 0x0 */
654	  reg_write(HOST_DPI_COLOR_CODING, COLOR_CODE_RGB565);
655	
656	  /* Set polarity: all active high (write 0) */
657	  reg_write(HOST_DPI_CFG_POL, 0);
658	
659	  /* Video mode configuration */
660	  uint32_t vid_mode_cfg = VID_MODE_TYPE_BURST;
661	  vid_mode_cfg |= LP_VSA_EN | LP_VBP_EN | LP_VFP_EN | LP_VACT_EN;
662	  vid_mode_cfg |= LP_HBP_EN | LP_HFP_EN;
663	  vid_mode_cfg |= FRAME_BTA_ACK_EN | LP_CMD_EN;
664	  reg_write(HOST_VID_MODE_CFG, vid_mode_cfg);
665	
666	  /* Set packet size = horizontal resolution */
667	  reg_write(HOST_VID_PKT_SIZE, ESP_DSI_HRES);
668	  reg_write(HOST_VID_NUM_CHUNKS, 0);
669	  reg_write(HOST_VID_NULL_SIZE, 0);
670	
671	  /* Horizontal timing in lane byte clock cycles */
672	  reg_write(HOST_VID_HSA_TIME, hsw_bytes);
673	  reg_write(HOST_VID_HBP_TIME, hbp_bytes);
674	  reg_write(HOST_VID_HLINE_TIME, hline_bytes);
675	
676	  /* Vertical timing in lines (no clock domain conversion) */
677	  reg_write(HOST_VID_VSA_LINES, ESP_DSI_VSYNC);
678	  reg_write(HOST_VID_VBP_LINES, ESP_DSI_VBP);
679	  reg_write(HOST_VID_VFP_LINES, ESP_DSI_VFP);
680	  reg_write(HOST_VID_VACTIVE_LINES, ESP_DSI_VRES);
681	
682	  syslog(LOG_INFO, "[DSI] DPI timing: HSA=%lu HBP=%lu HLINE=%lu\n",
683	         (unsigned long)hsw_bytes, (unsigned long)hbp_bytes,
684	         (unsigned long)hline_bytes);
685	}
