687	static void phase5_bridge_config(void)
688	{
689	  syslog(LOG_INFO, "[DSI] Phase 5b: Bridge config\n");
690	
691	  /* 1. Enable bridge clock */
692	  reg_write(BRG_CLK_EN, 1);
693	
694	  /* 2. Set pixel type for RGB565 input + RGB565 output:
695	   * raw_type[3:0]=2 (RGB565), data_in_type[6]=0, dpi_type[10:7]=2 (RGB565)
696	   */
697	  reg_write(BRG_PIXEL_TYPE, (2 << 0) | (2 << 7));
698	
699	  /* 3. Set total raw pixel bits (in 64-bit words) and trigger reload
700	   * total_pixel_bits = H * V * BPP = 1024 * 600 * 16 = 9,830,400
701	   * raw_num_total = total_pixel_bits / 64 = 153,600
702	   */
703	  uint32_t total_pixel_bits = (uint32_t)ESP_DSI_HRES * ESP_DSI_VRES *
704	                              ESP_DSI_FB_BPP;
705	  uint32_t raw_num_total = (total_pixel_bits + 63) / 64;
706	  uint32_t unalign = (total_pixel_bits % 64) ? 1 : 0;
707	  reg_write(BRG_RAW_NUM_CFG, (raw_num_total & 0x3FFFFF) |
708	            (unalign << 22) | (1u << 31));
709	
710	  /* 4. Set underrun discard count (in dpi_misc_config, bits[15:4]) */
711	  uint32_t misc = reg_read(BRG_DPI_MISC_CONFIG);
712	  misc &= ~(0xFFF << 4);
713	  misc |= ((ESP_DSI_HRES & 0xFFF) << 4);
714	  reg_write(BRG_DPI_MISC_CONFIG, misc);
715	
716	  /* 5. DMA configuration: burst_len=256 */
717	  reg_write(BRG_DMA_REQ_CFG, 256);
718	
719	  /* 6. Set block interval: enable interval, auto reload raw_num_total */
720	  reg_write(BRG_DMA_BLOCK_INTERVAL, (9 << 0) |     /* block_slot = 9 */
721	            (9 << 10) |                              /* block_interval = 9 */
722	            (1 << 28) |                              /* raw_num_total_auto_reload */
723	            (1 << 29));                              /* block_interval_en */
724	  reg_write(BRG_DMA_REQ_INTERVAL, 1);
725	
726	  /* 7. DPI LCD control: clear (dpishutdn=0, dpicolorm=0) */
727	  reg_write(BRG_DPI_LCD_CTL, 0);
728	
729	  /* 8. Vertical timing in bridge (per hw_ver3 struct):
730	   *    DPI_V_CFG0: vtotal[11:0] | vdisp[27:16]
731	   *    DPI_V_CFG1: vbank(=vbp)[11:0] | vsync[27:16]
732	   */
733	  uint32_t vtotal = ESP_DSI_VSYNC + ESP_DSI_VBP + ESP_DSI_VRES + ESP_DSI_VFP;
734	  reg_write(BRG_DPI_V_CFG0,
735	            (vtotal & 0xFFF) | ((ESP_DSI_VRES & 0xFFF) << 16));
736	  reg_write(BRG_DPI_V_CFG1,
737	            (ESP_DSI_VBP & 0xFFF) | ((ESP_DSI_VSYNC & 0xFFF) << 16));
738	
739	  /* 9. Horizontal timing in bridge:
740	   *    DPI_H_CFG0: htotal[11:0] | hdisp[27:16]
741	   *    DPI_H_CFG1: hbank(=hbp)[11:0] | hsync[27:16]
742	   */
743	  uint32_t htotal = ESP_DSI_HSYNC + ESP_DSI_HBP + ESP_DSI_HRES + ESP_DSI_HFP;
744	  reg_write(BRG_DPI_H_CFG0,
745	            (htotal & 0xFFF) | ((ESP_DSI_HRES & 0xFFF) << 16));
746	  reg_write(BRG_DPI_H_CFG1,
747	            (ESP_DSI_HBP & 0xFFF) | ((ESP_DSI_HSYNC & 0xFFF) << 16));
748	
749	  syslog(LOG_INFO, "[DSI] Bridge timing: vtotal=%lu vdisp=%d htotal=%lu hdisp=%d\n",
750	         (unsigned long)vtotal, ESP_DSI_VRES,
751	         (unsigned long)htotal, ESP_DSI_HRES);
752	
753	  /* 10. Enable bridge */
754	  reg_write(BRG_EN, 1);
755	
756	  /* 11. Update DPI config */
757	  reg_write(BRG_DPI_CONFIG_UPDATE, 1);
758	}
