474	/****************************************************************************
475	 * Name: esp_dsi_dma_isr_handler
476	 *
477	 * Description:
478	 *   Called from the shared DW-GDMA ISR (in esp_mipi_csi.c) when channel 1
479	 *   has pending interrupt status. Clears the interrupt and invokes the
480	 *   registered trans_done callback to re-arm DMA for continuous refresh.
481	 ****************************************************************************/
482	
483	void esp_dsi_dma_isr_handler(void)
484	{
485	  struct dw_gdma_channel_t *chan = &g_dsi_channel;
486	  dw_gdma_dev_t *dev = chan->dev;
487	  int ch = chan->chan_id;
488	  uint32_t status;
489	
490	  if (!g_dsi_channel_allocated || dev == NULL)
491	    {
492	      return;
493	    }
494	
495	  /* Read and clear channel 1 interrupt status */
496	
497	  status = dw_gdma_ll_channel_get_intr_status(dev, ch);
498	  if (status == 0)
499	    {
500	      return;
501	    }
502	
503	  dw_gdma_ll_channel_clear_intr(dev, ch, status);
504	
505	  /* If block transfer done, invoke callback to re-arm DMA */
506	
507	  if (chan->on_block_trans_done)
508	    {
509	      dw_gdma_trans_done_event_data_t ev;
510	      memset(&ev, 0, sizeof(ev));
511	      chan->on_block_trans_done(chan, &ev, chan->user_data);
512	    }
513	}
