static void fill_framebuffer(uint8_t *fb, size_t fb_size,
                             uint8_t r, uint8_t g, uint8_t b)
{
  volatile uint8_t *fb_nc;
  size_t i;

  if (fb == NULL || fb_size == 0)
    {
      return;
    }

  fb_nc = (volatile uint8_t *)((uintptr_t)fb + 0x40000000);

  for (i = 0; i + 2 < fb_size; i += 3)
    {
      fb[i + 0] = r;
      fb[i + 1] = g;
      fb[i + 2] = b;
      fb_nc[i + 0] = r;
      fb_nc[i + 1] = g;
      fb_nc[i + 2] = b;
    }
}

input.new_string:
static void fill_framebuffer(uint8_t *fb, size_t fb_size,
                             uint8_t r, uint8_t g, uint8_t b)
{
  volatile uint8_t *fb_nc;
  uint16_t pixel;
  uint8_t hi;
  uint8_t lo;
  size_t i;

  if (fb == NULL || fb_size < 2)
    {
      return;
    }

  fb_nc = (volatile uint8_t *)((uintptr_t)fb + 0x40000000);

  pixel = ((uint16_t)(r & 0xf8) << 8) |
          ((uint16_t)(g & 0xfc) << 3) |
          ((uint16_t)(b & 0xf8) >> 3);
  hi = (uint8_t)(pixel >> 8);
  lo = (uint8_t)(pixel & 0xff);

  for (i = 0; i + 1 < fb_size; i += 2)
    {
      fb[i + 0] = hi;
      fb[i + 1] = lo;
      fb_nc[i + 0] = hi;
      fb_nc[i + 1] = lo;
    }
}

