input.old_string:
static void fill_framebuffer(uint8_t *fb, size_t fb_size,
                             uint8_t r, uint8_t g, uint8_t b)
{
  volatile uint8_t *fb_nc;
  uint16_t pixel;
  uint8_t hi;
  uint8_t lo;
  size_t i;

  if (fb == NULL || fb_size < 2)
    {
      return;
    }

  fb_nc = (volatile uint8_t *)((uintptr_t)fb + 0x40000000);

  pixel = ((uint16_t)(r & 0xf8) << 8) |
          ((uint16_t)(g & 0xfc) << 3) |
          ((uint16_t)(b & 0xf8) >> 3);
  hi = (uint8_t)(pixel >> 8);
  lo = (uint8_t)(pixel & 0xff);

  for (i = 0; i + 1 < fb_size; i += 2)
    {
      fb[i + 0] = hi;
      fb[i + 1] = lo;
      fb_nc[i + 0] = hi;
      fb_nc[i + 1] = lo;
    }
}

input.new_string:
static void fill_framebuffer(uint8_t *fb, size_t fb_size,
                             uint8_t r, uint8_t g, uint8_t b)
{
  volatile uint16_t *fb16;
  volatile uint16_t *fb16_nc;
  uint16_t pixel;
  size_t count;
  size_t i;

  if (fb == NULL || fb_size < 2)
    {
      return;
    }

  fb16 = (volatile uint16_t *)fb;
  fb16_nc = (volatile uint16_t *)((uintptr_t)fb + 0x40000000);
  count = fb_size / 2;

  pixel = ((uint16_t)(r & 0xf8) << 8) |
          ((uint16_t)(g & 0xfc) << 3) |
          ((uint16_t)(b & 0xf8) >> 3);

  for (i = 0; i < count; i++)
    {
      fb16[i] = pixel;
      fb16_nc[i] = pixel;
    }
}

